package caseapp

import caseapp.core.Arg
import caseapp.core.help.{Help, HelpFormat}
import utest._

/** Checks that the overloads `@since` annotations ask for are there
  *
  * They're generated by data-class on Scala 2, and by the unroll compiler plugin on Scala 3.
  */
object BinaryCompatibilityTests extends TestSuite {

  private def check(clazz: Class[_], companion: Class[_], expectedArities: Set[Int]): Unit = {
    val ctorArities = clazz.getConstructors.map(_.getParameterCount).toSet
    val copyArities = clazz.getMethods.filter(_.getName == "copy").map(_.getParameterCount).toSet
    val applyArities =
      companion.getMethods.filter(_.getName == "apply").map(_.getParameterCount).toSet
    assert(expectedArities.subsetOf(ctorArities))
    assert(expectedArities.subsetOf(copyArities))
    assert(expectedArities.subsetOf(applyArities))
  }

  val tests = Tests {
    test("Arg") {
      check(classOf[Arg], Arg.getClass, Set(6, 7, 8, 9))
    }
    test("Help") {
      check(classOf[Help[_]], Help.getClass, Set(5, 8))
    }
    test("HelpFormat") {
      check(classOf[HelpFormat], HelpFormat.getClass, Set(11, 12, 14, 15))
    }
  }

}
